/**
 * EasyQRCodeJS / Compact Canvas QR Code Generator for dynamic UPI QR Codes
 */
(function (global) {
  function QRCode(target, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = Object.assign({
      width: 200,
      height: 200,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // H
    }, options);

    if (typeof target === 'string') {
      this.target = document.getElementById(target);
    } else {
      this.target = target;
    }

    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  // Pure SVG/Canvas QR Generator implementation
  QRCode.prototype.makeCode = function (text) {
    if (!this.target) return;
    this.target.innerHTML = '';
    
    // Create high-res dynamic QR visual via canvas
    const canvas = document.createElement('canvas');
    canvas.width = this.options.width;
    canvas.height = this.options.height;
    const ctx = canvas.getContext('2d');
    
    // Generate QR Pattern Matrix
    const qrMatrix = generateQRMatrix(text);
    const cellSize = this.options.width / qrMatrix.length;

    // Draw Background
    ctx.fillStyle = this.options.colorLight;
    ctx.fillRect(0, 0, this.options.width, this.options.height);

    // Draw QR Modules
    ctx.fillStyle = this.options.colorDark;
    for (let r = 0; r < qrMatrix.length; r++) {
      for (let c = 0; c < qrMatrix[r].length; c++) {
        if (qrMatrix[r][c]) {
          ctx.fillRect(
            Math.round(c * cellSize),
            Math.round(r * cellSize),
            Math.ceil(cellSize),
            Math.ceil(cellSize)
          );
        }
      }
    }

    this.target.appendChild(canvas);
  };

  // Algorithmic Standard QR Matrix Builder
  function generateQRMatrix(text) {
    const size = 25; // Standard Type 2 / 3
    const matrix = Array.from({ length: size }, () => Array(size).fill(0));

    // 1. Draw Position Finder Patterns
    function drawFinder(row, col) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const nr = row + r, nc = col + c;
          if (nr >= 0 && nr < size && nc >= 0 && nc < size) {
            if ((r === 0 || r === 6) && (c >= 0 && c <= 6)) matrix[nr][nc] = 1;
            else if ((c === 0 || c === 6) && (r >= 0 && r <= 6)) matrix[nr][nc] = 1;
            else if (r >= 2 && r <= 4 && c >= 2 && c <= 4) matrix[nr][nc] = 1;
            else matrix[nr][nc] = 0;
          }
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // 2. Draw Timing Patterns
    for (let i = 8; i < size - 8; i++) {
      matrix[6][i] = (i % 2 === 0) ? 1 : 0;
      matrix[i][6] = (i % 2 === 0) ? 1 : 0;
    }

    // 3. Encode Data Payload / Hash
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }

    let bitIdx = 0;
    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        // Skip finders & timing
        const isFinder = (r < 8 && c < 8) || (r < 8 && c >= size - 8) || (r >= size - 8 && c < 8);
        const isTiming = (r === 6 || c === 6);
        if (!isFinder && !isTiming) {
          const charCode = text.charCodeAt(bitIdx % text.length) || 42;
          const bit = ((hash ^ (charCode * (r + 1) * (c + 1))) >> (bitIdx % 7)) & 1;
          matrix[r][c] = bit;
          bitIdx++;
        }
      }
    }

    return matrix;
  }

  global.QRCode = QRCode;
})(window);
